#!/usr/bin/env bash
# G1 harness wrapper: the nested CDE `terminal`. Records its pid, optionally enables WAYLAND_DEBUG with stderr to a
# per-window log, then execs the real terminal (PROG/PRE from $G1_DIR/term.env), so the process tree is unchanged.
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'scripts/g1/term.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'term.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
set -euo pipefail

usage() {
	cat <<'USAGE'
Usage: term.sh [--help|--build|--version] [terminal args...]

Wrapper used as the nested CDE `terminal` by scripts/g1/g1.sh. Requires G1_DIR (the scratch dir holding term.env,
the pids file and an optional `debug` marker). Appends its pid to $G1_DIR/pids, then execs $PROG $PRE "$@";
with $G1_DIR/debug present it sets WAYLAND_DEBUG=1 and sends stderr to $G1_DIR/wl.<pid>.log.
  --help     print this text, exit 0
  --build / --version   print the tool-scoped build id, exit 0
Only a lone first argument is treated as a flag; everything else is passed to the terminal.
USAGE
}

# shellcheck source-path=SCRIPTDIR source=../lib/build-id.sh
. "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")/../lib/build-id.sh"
if [ "$#" -eq 1 ]; then
	case $1 in
	--help | -h)
		usage
		exit 0
		;;
	--build | --version)
		build_id "${BASH_SOURCE[0]}"
		exit 0
		;;
	esac
fi

: "${G1_DIR:?term.sh: G1_DIR is not set (run via scripts/g1/g1.sh)}"
# shellcheck disable=SC1091
. "$G1_DIR/term.env"
echo $$ >>"$G1_DIR/pids"
if [ -e "$G1_DIR/debug" ]; then
	export WAYLAND_DEBUG=1
	# shellcheck disable=SC2086
	exec $PROG $PRE "$@" 2>"$G1_DIR/wl.$$.log"
fi
# shellcheck disable=SC2086
exec $PROG $PRE "$@"
